import{_ as e,o as l,c as o,a3 as t}from"./chunks/framework.BveOjhN0.js";const b=JSON.parse('{"title":"增量更新","description":"","frontmatter":{"title":"增量更新"},"headers":[],"relativePath":"zh/08.plugins/02.incremental-update.md","filePath":"zh/08.plugins/02.incremental-update.md","lastUpdated":1782655224000}'),n={name:"zh/08.plugins/02.incremental-update.md"};function r(i,a,d,c,h,p){return l(),o("div",null,[...a[0]||(a[0]=[t('<p>增量更新有以下优点：</p><ol><li>绕过macOS 权限，无需购买开发者账号（可节省 600元/每年）。</li><li>如果上架其它平台应用商店 ，理论上也可以绕过官方的升级方式。</li><li>减小更新包大小，约4～10 倍，减少大量cdn资源费用。</li><li>用户重启即可完成更新，不需要走安装流程。</li><li>全量更新会删除本地数据，增量更新不会影响本地数据。</li><li>支持 <code>windows</code>、<code>macOS-intel</code>、<code>macOS-m芯片</code> 平台。</li><li>插件提供了一些 api，可以让开发者自定义一些功能。</li></ol><h3 id="demo" tabindex="-1">demo <a class="header-anchor" href="#demo" aria-label="Permalink to &quot;demo&quot;">​</a></h3><p>插件文档中提供了完成的 demo，包括页面效果，易于使用。（购买后联系作者）</p><h4 id="cdn" tabindex="-1">CDN <a class="header-anchor" href="#cdn" aria-label="Permalink to &quot;CDN&quot;">​</a></h4><p><a href="https://s.qiniu.com/BbAjMv" target="_blank" rel="noreferrer">七牛云</a>每月10G<code>免费</code>流量，满足日常使用。</p><h3 id="购买" tabindex="-1">购买 <a class="header-anchor" href="#购买" aria-label="Permalink to &quot;购买&quot;">​</a></h3><p>添加微信</p><img style="zoom:20%;" src="https://img01.kaka996.com/ee/wx-2.jpg"><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><p>插件提供一些 api，可以让开发者自定义一些功能。</p><h4 id="setconfig" tabindex="-1">setConfig() <a class="header-anchor" href="#setconfig" aria-label="Permalink to &quot;setConfig()&quot;">​</a></h4><p>设置基础配置</p><h4 id="on-update-available-callback" tabindex="-1">on(&#39;update-available&#39;, callback) <a class="header-anchor" href="#on-update-available-callback" aria-label="Permalink to &quot;on(&#39;update-available&#39;, callback)&quot;">​</a></h4><p>监听可用更新事件</p><h4 id="on-update-not-available-callback" tabindex="-1">on(&#39;update-not-available&#39;, callback) <a class="header-anchor" href="#on-update-not-available-callback" aria-label="Permalink to &quot;on(&#39;update-not-available&#39;, callback)&quot;">​</a></h4><p>监听不可用更新事件</p><h4 id="on-download-progress-callback" tabindex="-1">on(&#39;download-progress&#39;, callback) <a class="header-anchor" href="#on-download-progress-callback" aria-label="Permalink to &quot;on(&#39;download-progress&#39;, callback)&quot;">​</a></h4><p>监听下载进度事件</p><h4 id="on-update-downloaded-callback" tabindex="-1">on(&#39;update-downloaded&#39;, callback) <a class="header-anchor" href="#on-update-downloaded-callback" aria-label="Permalink to &quot;on(&#39;update-downloaded&#39;, callback)&quot;">​</a></h4><p>监听下载完成事件</p><h4 id="on-error-callback" tabindex="-1">on(&#39;error&#39;, callback) <a class="header-anchor" href="#on-error-callback" aria-label="Permalink to &quot;on(&#39;error&#39;, callback)&quot;">​</a></h4><p>监听下载错误事件</p><h4 id="checkavailable" tabindex="-1">checkAvailable() <a class="header-anchor" href="#checkavailable" aria-label="Permalink to &quot;checkAvailable()&quot;">​</a></h4><p>检查更新</p><h4 id="download" tabindex="-1">download() <a class="header-anchor" href="#download" aria-label="Permalink to &quot;download()&quot;">​</a></h4><p>下载</p><h4 id="installapp" tabindex="-1">installApp() <a class="header-anchor" href="#installapp" aria-label="Permalink to &quot;installApp()&quot;">​</a></h4><p>安装</p><h4 id="byteschange" tabindex="-1">bytesChange() <a class="header-anchor" href="#byteschange" aria-label="Permalink to &quot;bytesChange()&quot;">​</a></h4><p>将字节数转换为可读的字符串</p>',31)])])}const u=e(n,[["render",r]]);export{b as __pageData,u as default};
